-- SQL Server 2016+ / Visual Studio SQL editor / SSMS / sqlcmd
-- Real observations: Hanoi Air Quality Monitoring Network via OpenAQ.
-- Stations: Hang Dau (2161299), Khuong Trung (2161301); year 2024.
-- Source: https://openaq-data-archive.s3.amazonaws.com/records/csv.gz/
-- UTF-8 BOM; Unicode strings; original timestamps retain +07:00.
-- Re-running adds missing keys only; differing existing records cause rollback.
-- Does not drop databases, delete observations, or update existing records.
USE [master];
GO
IF DB_ID(N'hanoi_air_vn') IS NULL
    EXEC(N'CREATE DATABASE [hanoi_air_vn]');
GO
USE [hanoi_air_vn];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
    BEGIN TRANSACTION;
    IF OBJECT_ID(N'dbo.air_quality_hourly', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.air_quality_hourly (
            id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_air_quality_hourly PRIMARY KEY,
            location_id INT NOT NULL,
            sensor_id INT NOT NULL,
            location_name NVARCHAR(160) NOT NULL,
            observed_at DATETIMEOFFSET(0) NOT NULL,
            latitude DECIMAL(10,6) NULL,
            longitude DECIMAL(10,6) NULL,
            parameter NVARCHAR(20) NOT NULL,
            unit NVARCHAR(40) NOT NULL,
            value FLOAT(53) NULL,
            CONSTRAINT UQ_air_measurement UNIQUE (location_id,sensor_id,observed_at,parameter)
        );
    END;
    CREATE TABLE #source (
        location_id INT NOT NULL, sensor_id INT NOT NULL, location_name NVARCHAR(160) NOT NULL,
        observed_at DATETIMEOFFSET(0) NOT NULL, latitude DECIMAL(10,6), longitude DECIMAL(10,6),
        parameter NVARCHAR(20) NOT NULL, unit NVARCHAR(40) NOT NULL, value FLOAT(53)
    );
    SELECT location_id,sensor_id,location_name,observed_at,latitude,longitude,parameter,unit,value FROM #source AS s
    WHERE NOT EXISTS (SELECT 1 FROM dbo.air_quality_hourly AS t
        WHERE t.location_id=s.location_id AND t.sensor_id=s.sensor_id
          AND t.observed_at=s.observed_at AND t.parameter=s.parameter);
    IF EXISTS (SELECT location_id,sensor_id,location_name,observed_at,latitude,longitude,parameter,unit,value FROM #source EXCEPT SELECT location_id,sensor_id,location_name,observed_at,latitude,longitude,parameter,unit,value FROM dbo.air_quality_hourly)
        THROW 50001, 'Existing records differ from source; import rolled back.', 1;
    DROP TABLE #source;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO
SELECT COUNT_BIG(*) AS total_measurements FROM dbo.air_quality_hourly;
SELECT location_id, location_name, parameter, unit, COUNT_BIG(*) AS measurements,
       MIN(observed_at) AS first_observation, MAX(observed_at) AS last_observation
FROM dbo.air_quality_hourly GROUP BY location_id, location_name, parameter, unit
ORDER BY location_id, parameter;
-- Source measurements: 23036; source files: 325
